function findNestedKeyValue(obj, strKey) {
  const keys = strKey.split('.');
  let currentObj = obj;

  for (let i = 0; i < keys.length; i++) {
    if (!_.isUndefined(currentObj[keys[i]])) {
      currentObj = currentObj[keys[i]];
    } else {
      throw new Error(`Key "${strKey}" not found in object.`);
    }
  }

  return currentObj;
}

// Example usage:
