 To retrieve the username from a JWT (JSON Web Token) in an ASP.NET C# WebApi, you'll first need to parse the token. Here's a step-by-step guide on how to accomplish this:

1. Install the `Microsoft.IdentityModel.Tokens` NuGet package to your project:
   Open Terminal or Package Manager Console and run:
   ```
   Install-Package Microsoft.IdentityModel.Tokens
   ```
2. Create an extension method for parsing JWT tokens:
   Add a new file named `JwtExtensions.cs` to your project, then add the following code:

```csharp
using System;
using System.IdentityModel.Tokens.Jwt;

public static class JwtExtensions
{
    public static string GetUsernameFromJwtToken(this string jwtToken)
    {
        var handler = new JwtSecurityTokenHandler();

        try
        {
            var jwtTokenObj = handler.ReadJwtToken(jwtToken);
            return jwtTokenObj.Claims.FirstOrDefault(x => x.Type == ClaimTypes.Name)?.Value;
        }
        catch (Exception ex)
        {
            throw new ArgumentException("Invalid JWT token.", nameof(jwtToken));
        }
    }
}
```

3. Use the extension method to get the username from the JWT token in your controller action:

```csharp
using Microsoft.AspNetCore.Mvc;
using YourProjectNamespace.Extensions; // Replace "YourProjectNamespace" with your actual project namespace

[Route("api/[controller]")]
[ApiController]
public class ValuesController : ControllerBase
{
    [HttpGet]
    public ActionResult<string> Get()
    {
        string jwtToken = Request.Headers["Authorization"].Split(" ")[1]; // Get JWT token from Authorization header
        string username = jwtToken.GetUsernameFromJwtToken(); // Call extension method to extract username from JWT token

        return Ok($"Hello, {username}!");
    }
}
```

