```php
<?php
// Assume we have a connection to the database $conn established earlier

$product = 'coffee'; // Replace with the name of the specific product
$week_start = date('Y-m-d', strtotime('-1 week'));
$week_end = date('Y-m-d');

$sql = "SELECT customers.name, COUNT(*) as num_purchases
        FROM transactions
        JOIN products ON transactions.product_id = products.id
        WHERE products.name = '$product'
        AND transactions.transaction_date BETWEEN '$week_start' AND '$week_end'
        GROUP BY transactions.customer_id
        HAVING num_purchases >= 3";

$result = mysqli_query($conn, $sql);

if (mysqli_num_rows($result) > 0) {
    while($row = mysqli_fetch_assoc($result)) {
        echo $row["name"] . " purchased " . $row["num_purchases"] . " " . $product . "s this week.\n";
    }
} else {
    echo "No loyal customers found for the specified product this week.";
}

mysqli_close($conn);
?>
```

