```javascript
async function checkMediaPermissions() {
  const mediaStreamConstraints = { audio: true, video: true };
  try {
    const stream = await navigator.mediaDevices.getUserMedia(mediaStreamConstraints);
    return { cameraAllowed: stream.videoTracks.length > 0, microphoneAllowed: stream.audioTracks.length > 0 };
  } catch (error) {
    console.error('Error getting user media permissions:', error);
    return { cameraAllowed: false, microphoneAllowed: false };
  }
}
```

2. **openCamera()**: This method opens the camera and returns a Promise that resolves with the VideoStreamTrack object.

```javascript
async function openCamera() {
  const mediaStreamConstraints = { video: true, audio: false };
  try {
    const stream = await navigator.mediaDevices.getUserMedia(mediaStreamConstraints);
    const videoTrack = stream.getVideoTracks()[0];
    return new Promise((resolve) => {
      videoTrack.onended = () => resolve(videoTrack);
    });
  } catch (error) {
    console.error('Error opening camera:', error);
    throw new Error('Could not open camera');
  }
}
```

